import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def legendre(n, p):
    count = 0
    i = p
    while i <= n:
        count += n // i
        i *= p
    return count

def omega_n_factorial_2023(n):
    if n < 34:
        return float('inf') # Not an integer

    # Numerator is n!
    # Denominator is 2023 = 7^1 * 17^2

    # Calculate v_p(n! / 2023) for all primes p <= n
    prime_factors_count = set()

    # Find all primes up to n
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(math.sqrt(n)) + 1):
        if is_prime[p]:
            for multiple in range(p*p, n + 1, p):
                is_prime[multiple] = False

    primes = [p for p in range(2, n + 1) if is_prime[p]]

    for p in primes:
        v_p_n_fact = legendre(n, p)
        v_p_2023 = 0
        if p == 7:
            v_p_2023 = 1
        elif p == 17:
            v_p_2023 = 2

        exponent = v_p_n_fact - v_p_2023
        if exponent > 0:
            prime_factors_count.add(p)

    return len(prime_factors_count)

print(f"omega(34!/2023): {omega_n_factorial_2023(34)}")
print(f"omega(40!/2023): {omega_n_factorial_2023(40)}")
print(f"omega(41!/2023): {omega_n_factorial_2023(41)}")
