def count_primes(n):
    """Counts the number of primes less than or equal to n."""
    if n < 2:
        return 0
    count = 0
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p*p, n + 1, p):
                is_prime[i] = False
    for i in range(2, n + 1):
        if is_prime[i]:
            count += 1
    return count

